import random
import sys
from datetime import datetime, timedelta

sys.path.insert(0, "/private/tmp/tmp7g83y86w/pete/projects/devkit")
from devkit.cron import next_run

random.seed(20261026)


def add_years(dt, years):
    try:
        return dt.replace(year=dt.year + years)
    except ValueError:
        return dt.replace(year=dt.year + years, day=28)


def item(values, low):
    """Render a sorted value set as a comma list, using ranges when contiguous."""
    values = sorted(values)
    if values == list(range(low, max(values) + 1)) and len(values) > 2:
        return "*"
    parts = []
    i = 0
    while i < len(values):
        j = i
        while j + 1 < len(values) and values[j + 1] == values[j] + 1:
            j += 1
        if j - i >= 2:
            parts.append("%d-%d" % (values[i], values[j]))
        else:
            parts.extend(str(v) for v in values[i : j + 1])
        i = j + 1
    return ",".join(parts)


def reference(minutes, hours, doms, months, dows, after):
    """Independent day scan over parsed value sets."""
    py_dows = {(d + 6) % 7 for d in dows}
    dom_restricted = doms != set(range(1, 32))
    dow_restricted = dows != set(range(0, 8))
    times = sorted(h * 60 + m for h in hours for m in minutes)
    limit = add_years(after, 5)
    cutoff = after.hour * 60 + after.minute
    day = after.date()
    while day <= limit.date():
        if day.month in months:
            a = day.day in doms
            b = day.weekday() in py_dows
            if dom_restricted and dow_restricted:
                ok = a or b
            else:
                ok = a and b
            if ok:
                if day == after.date():
                    minutes_today = [t for t in times if t > cutoff]
                    t = minutes_today[0] if minutes_today else None
                else:
                    t = times[0]
                if t is not None:
                    candidate = datetime(day.year, day.month, day.day, t // 60, t % 60)
                    if candidate <= limit:
                        return candidate
                    return None
        day += timedelta(days=1)
    return None


checked = 0
for _ in range(500):
    minutes = set(random.sample(range(60), random.randint(1, 4)))
    hours = set(random.sample(range(24), random.randint(1, 4)))
    if random.random() < 0.5:
        doms = set(range(1, 32))
    else:
        doms = set(random.sample(range(1, 32), random.randint(1, 3)))
        if random.random() < 0.3:
            # Make it impossible in some months more often.
            doms = {random.choice([29, 30, 31])}
    if random.random() < 0.5:
        months = set(range(1, 13))
    else:
        months = set(random.sample(range(1, 13), random.randint(1, 3)))
    if random.random() < 0.5:
        dows = set(range(0, 8))
    else:
        dows = set(random.choice([[0], [7], [1], [5], [6], [0, 6], [1, 2, 3, 4, 5], [5, 6, 7]]))

    expr = " ".join(
        [
            item(minutes, 0),
            item(hours, 0),
            item(doms, 1),
            item(months, 1),
            item(dows, 0),
        ]
    )
    after = datetime(
        random.randint(2026, 2090),
        random.randint(1, 12),
        random.randint(1, 28),
        random.randint(0, 23),
        random.randint(0, 59),
        random.randint(0, 59),
        random.randint(0, 999999),
    )
    expected = reference(minutes, hours, doms, months, dows, after)
    try:
        got = next_run(expr, after)
    except ValueError:
        got = None
    assert got == expected, (expr, after, got, expected)
    if expected is not None:
        assert got > after and got.second == got.microsecond == 0
    checked += 1

print("fuzz cases passed:", checked)

